const inp = $('When Called as Tool').first().json;
const cfg = $('Client Config').first().json;
const services = $('Get Services Catalog').all().map(i => i.json).filter(r => r && r.id !== undefined && r.id !== null);
const rows = $('Get Upcoming Bookings').all().map(i => i.json).filter(r => r && r.id !== undefined && r.id !== null && String(r.status || '').toLowerCase() !== 'cancelled');
const nowMs = Date.now();
const holdsAll = $('Get Active Holds').all().map(i => i.json).filter(h => h && h.booking_date && h.booking_time && h.released !== true && Number(h.expires_ms) > nowMs);
const fail = (code, message) => [{ json: { ok: false, error_code: code, message: message } }];
const pad = n => String(n).padStart(2, '0');

// ---------- smart phone and name helpers ----------
const AR_D = '٠١٢٣٤٥٦٧٨٩', FA_D = '۰۱۲۳۴۵۶۷۸۹';
const normPhone = p => {
  let d = String(p || '').replace(/[٠-٩]/g, c => AR_D.indexOf(c)).replace(/[۰-۹]/g, c => FA_D.indexOf(c)).replace(/\D/g, '');
  if (d.startsWith('0020')) d = '0' + d.slice(4);
  else if (d.length === 12 && d.startsWith('20')) d = '0' + d.slice(2);
  else if (d.length === 10 && /^1[0125]/.test(d)) d = '0' + d;
  return d;
};
const isAr = s => /[\u0600-\u06FF]/.test(s);
const clean = s => String(s || '').toLowerCase()
  .replace(/[\u064B-\u065F\u0670\u0640]/g, '')
  .replace(/[أإآٱ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه').replace(/ؤ/g, 'و').replace(/ئ/g, 'ي')
  .replace(/[^\p{L}\s]/gu, ' ').replace(/\s+/g, ' ').trim()
  .replace(/(^| )(ال|el|al) /g, '$1$2')
  .replace(/(^| )(عبد|abdel|abdul|abdal|abdu|abd) /g, '$1$2');
const AR_SK = { 'ب':'b','ت':'t','ث':'s','ج':'j','ح':'h','خ':'x','د':'d','ذ':'z','ر':'r','ز':'z','س':'s','ش':'S','ص':'s','ض':'d','ط':'t','ظ':'z','غ':'G','ف':'f','ق':'k','ك':'k','ل':'l','م':'m','ن':'n','ه':'h' };
const fin = s => s.replace(/(.)\1+/g, '$1').replace(/^(.{2,})h$/, '$1');
const skel = w => {
  if (isAr(w)) return fin([...w].map(c => AR_SK[c] || '').join(''));
  const s = w.replace(/sh|ch/g, 'S').replace(/kh/g, 'x').replace(/gh/g, 'G').replace(/th/g, 's').replace(/dh/g, 'z').replace(/ph/g, 'f').replace(/ck/g, 'k').replace(/[cq]/g, 'k').replace(/g/g, 'j').replace(/v/g, 'f').replace(/p/g, 'b').replace(/[^a-zA-Z]/g, '');
  return fin(s.replace(/[aeiouyw]/g, ''));
};
const lev = (a, b) => {
  const m = a.length, n = b.length;
  const d = Array.from({ length: m + 1 }, (_, i) => { const r = new Array(n + 1).fill(0); r[0] = i; return r; });
  for (let j = 1; j <= n; j++) d[0][j] = j;
  for (let i = 1; i <= m; i++) for (let j = 1; j <= n; j++) d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[m][n];
};
// a = word the customer typed, b = registered word (both already cleaned)
const wordRel = (a, b) => {
  if (a === b) return 'same';
  const sa = skel(a), sb = skel(b);
  if (isAr(a) !== isAr(b)) {
    if (sa && sa === sb) return sa.length >= 2 ? 'same' : 'close';
    if (sa.length >= 3 && lev(sa, sb) <= 1) return 'close';
    return 'none';
  }
  const mx = Math.max(a.length, b.length);
  const lim = mx >= 7 ? 2 : (mx >= 4 ? 1 : 0);
  if (a[0] === b[0] && lev(a, b) <= lim) return 'close';
  if (sa.length >= 2 && sa === sb) return 'close';
  if (sa.length >= 3 && a[0] === b[0] && mx >= 5 && lev(sa, sb) <= 1) return 'close';
  return 'none';
};
// the leading article (ال / el / al) is ignored when comparing words
const noArt = w => isAr(w) ? (w.length > 4 && w.startsWith('ال') ? w.slice(2) : w) : (w.length > 5 && /^(el|al)/.test(w) ? w.slice(2) : w);
const nameRel = (inName, regName) => {
  const I = clean(inName).split(' ').filter(Boolean).map(noArt), R = clean(regName).split(' ').filter(Boolean).map(noArt);
  const used = new Set(); let matched = 0, allSame = true;
  for (const w of I) {
    let bestRank = 0, bestIdx = -1;
    R.forEach((r, i) => { if (used.has(i)) return; const rel = wordRel(w, r); const rk = rel === 'same' ? 2 : rel === 'close' ? 1 : 0; if (rk > bestRank) { bestRank = rk; bestIdx = i; } });
    if (bestIdx >= 0) { used.add(bestIdx); matched++; if (bestRank < 2) allSame = false; }
  }
  if (matched < Math.min(2, I.length, R.length)) return 'none';
  return allSame ? 'same' : 'close';
};

if (String(cfg.secret_key).indexOf('PASTE_') === 0 || String(cfg.public_key).indexOf('PASTE_') === 0 || !/^[0-9]+$/.test(String(cfg.integration_id))) {
  return fail('CONFIG_MISSING', 'The payment gateway is not configured yet. Apologize, do not promise a booking, and call escalate_to_human.');
}

const chatId = String(inp.chat_id || '').trim();
const kind = String(inp.kind || 'new').trim().toLowerCase();
const name = String(inp.customer_name || '').trim().replace(/\s+/g, ' ');
const phone = normPhone(inp.customer_phone);
if (kind !== 'new' && kind !== 'topup' && kind !== 'check') return fail('INVALID_REQUEST', 'kind must be new, topup or check.');
if (!chatId) return fail('INVALID_REQUEST', 'Missing chat id.');

const words = name.split(' ');
if (words.length < 2 || !words.every(w => /^[\p{L}.'-]+$/u.test(w))) {
  return fail('INVALID_NAME', 'The full name needs at least two words, letters only. Kindly ask for the first name and the family name. Do not proceed.');
}
if (!/^01[0125][0-9]{8}$/.test(phone)) {
  const why = phone.length !== 11 ? 'it has ' + phone.length + ' digits instead of 11' : 'it must start with 010, 011, 012 or 015';
  return fail('INVALID_PHONE', 'The phone is not a valid Egyptian mobile (' + why + '). Kindly ask the customer to resend an 11-digit number starting with 010, 011, 012 or 015.');
}

// ---------- identity: smart, never harsh ----------
const mine = rows.filter(r => String(r.customer_chat_id || '') === chatId);
const others = rows.filter(r => String(r.customer_chat_id || '') !== chatId);
if (others.some(r => normPhone(r.customer_phone) === phone)) {
  return fail('PHONE_USED_BY_OTHER_ACCOUNT', 'This phone number is already linked to another Telegram account, so it cannot be used from this account. Say so kindly WITHOUT revealing anything about the other account, and ask whether the customer wants to continue with a different mobile number. Offer escalate_to_human only if they insist or need help.');
}
const accPhones = [...new Set(mine.map(r => normPhone(r.customer_phone)).filter(Boolean))];
let finalName = name;
let idStatus = 'OK_NEW_CUSTOMER';
if (accPhones.includes(phone)) {
  idStatus = 'OK_PHONE_MATCHES_ACCOUNT';
  const regNames = [...new Set(mine.filter(r => normPhone(r.customer_phone) === phone).map(r => String(r.customer_name || '').trim()).filter(Boolean))];
  if (regNames.length) {
    const rank = { same: 2, close: 1, none: 0 };
    let best = { rel: 'none', name: regNames[0] };
    for (const rn of regNames) { const rel = nameRel(name, rn); if (rank[rel] > rank[best.rel]) best = { rel: rel, name: rn }; }
    if (best.rel === 'same') {
      finalName = best.name;
    } else if (best.rel === 'close') {
      return fail('NAME_SUGGESTION', 'The name is close to the name registered for this phone on this account: [' + best.name + ']. Ask kindly: هل تقصد ' + best.name + '؟ If the customer says yes, call again using EXACTLY that registered name. If no, tell them this number is registered under that name and ask whether to continue with it or to use another phone number. Do not proceed meanwhile.');
    } else {
      return fail('NAME_DIFFERS_FROM_RECORD', 'This phone is registered on this Telegram account under the name [' + best.name + '], which is different from the name given. Kindly tell the customer, and ask whether to continue with the registered name or to book with another phone number. Do not proceed meanwhile.');
    }
  }
} else if (accPhones.length) {
  if (String(inp.confirm_new_phone || '').trim().toLowerCase() !== 'yes') {
    return fail('NEW_PHONE_NEEDS_CONFIRMATION', 'This account already has a booking with another phone number (ending ' + accPhones.map(p => p.slice(-4)).join(' / ') + '). Ask kindly: الرقم ده مختلف عن الرقم المسجل على حسابك (بينتهي بـ ' + accPhones[0].slice(-4) + '). تحب نكمل بالرقم الجديد ولا بالرقم المسجل؟ If the customer confirms the NEW number, call again with confirm_new_phone=yes. If they prefer the registered one, ask them to send it in full.');
  }
  idStatus = 'OK_NEW_PHONE_CONFIRMED';
}

if (kind === 'check') {
  return [{ json: { ok: true, check_only: 'yes', status: idStatus, normalized_phone: phone, name_to_use: finalName, message: 'Identity check passed. Use name_to_use and normalized_phone in every following step.' } }];
}

const findSvc = id => services.find(s => String(s.id) === String(id));
const pct = Number(cfg.deposit_percent);
const disc = Number(cfg.addon_discount_percent);
const depositFor = (price, d) => Math.round(Number(price) * (1 - d / 100) * pct / 100);
const svc = findSvc(inp.service_id);
if (!svc || !(Number(svc.price) > 0)) {
  return fail('SERVICE_NOT_FOUND', 'Unknown service_id. Call get_business_info and use the exact id.');
}

let items = [];
if (kind === 'topup') {
  const b = mine.find(r => String(r.id) === String(inp.booking_id));
  if (!b) return fail('BOOKING_NOT_FOUND', 'No active booking with that id on this Telegram account.');
  const total = depositFor(svc.price, 0);
  const paid = String(b.payment_status) === 'paid' ? (Number(b.deposit_amount) || 0) : 0;
  const due = total - paid;
  if (due <= 0) return fail('NO_PAYMENT_DUE', 'No extra payment is needed. Use change_service instead.');
  items = [{ service_id: String(svc.id), service_name: svc.name, booking_id: b.id, booking_date: String(b.booking_date).slice(0, 10), booking_time: String(b.booking_time).slice(0, 5), deposit_amount: due, deposit_total: total }];
} else {
  const date = String(inp.booking_date || '').trim();
  const time = String(inp.booking_time || '').trim().slice(0, 5);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return fail('INVALID_DATE', 'booking_date must be YYYY-MM-DD.');
  const cairo = new Date(new Date().toLocaleString('en-US', { timeZone: 'Africa/Cairo' }));
  const today = cairo.getFullYear() + '-' + pad(cairo.getMonth() + 1) + '-' + pad(cairo.getDate());
  const lastDay = new Date(cairo.getFullYear(), cairo.getMonth(), cairo.getDate() + 13);
  const lastStr = lastDay.getFullYear() + '-' + pad(lastDay.getMonth() + 1) + '-' + pad(lastDay.getDate());
  if (date < today || date > lastStr) return fail('INVALID_DATE', 'The date must be within the next 14 days.');
  const nowMin = cairo.getHours() * 60 + cairo.getMinutes();
  const okTime = t => /^1[0-7]:00$/.test(t);
  const pastToday = t => date === today && parseInt(t.slice(0, 2), 10) * 60 <= nowMin;
  const booked = t => rows.some(r => String(r.booking_date).slice(0, 10) === date && String(r.booking_time).slice(0, 5) === t);
  const heldByOther = t => holdsAll.some(h => String(h.chat_id) !== chatId && String(h.booking_date) === date && String(h.booking_time).slice(0, 5) === t);
  const taken = t => booked(t) || heldByOther(t);
  if (!okTime(time) || pastToday(time)) return fail('INVALID_TIME', 'Times are on the hour from 10:00 to 17:00 and must be in the future.');
  if (taken(time)) return fail('SLOT_TAKEN', 'That time is no longer available (booked, or held by another customer who is paying right now). Offer the nearest free times from LIVE AVAILABILITY.');
  const dup = mine.find(r => String(r.booking_date).slice(0, 10) === date && String(r.id) !== String(inp.replaces_booking_id || ''));
  if (dup) {
    return fail('SAME_DAY_DUPLICATE', 'This customer already has an active booking on that date at ' + String(dup.booking_time).slice(0, 5) + ' (booking id ' + dup.id + '). Ask whether to move it with reschedule_booking or cancel it first, then pass replaces_booking_id.');
  }
  items = [{ service_id: String(svc.id), service_name: svc.name, booking_id: null, booking_date: date, booking_time: time, deposit_amount: depositFor(svc.price, 0) }];
  const addonId = String(inp.addon_service_id || '').trim();
  if (addonId) {
    const a = findSvc(addonId);
    const at = String(inp.addon_time || '').trim().slice(0, 5);
    if (!a || !(Number(a.price) > 0) || addonId === String(svc.id)) return fail('SERVICE_NOT_FOUND', 'Unknown or duplicate addon_service_id.');
    if (!okTime(at) || pastToday(at) || at === time || taken(at)) return fail('SLOT_TAKEN', 'The add-on time is not free. Pick another free time on the same date or skip the add-on.');
    items.push({ service_id: String(a.id), service_name: a.name, booking_id: null, booking_date: date, booking_time: at, deposit_amount: depositFor(a.price, disc) });
  }
}

const amount = items.reduce((s, i) => s + i.deposit_amount, 0);
if (!(amount >= 1)) return fail('INVALID_AMOUNT', 'The computed deposit is below 1 EGP.');
const reference = 'BK-' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 6).toUpperCase();
const cents = a => Math.round(a) * 100;
// New bookings hold their slot(s) for the link lifetime plus a 5 minute grace period
const holdExpiresMs = kind === 'new' ? nowMs + (Number(cfg.link_valid_seconds) + 300) * 1000 : 0;
const holds = kind === 'new' ? items.map(i => ({ chat_id: chatId, booking_date: i.booking_date, booking_time: i.booking_time, expires_ms: holdExpiresMs, released: false })) : [];
const fw = finalName.split(' ');
const body = {
  amount: cents(amount),
  currency: cfg.currency,
  payment_methods: [Number(cfg.integration_id)],
  items: items.map(i => ({ name: String(i.service_name || 'Service').slice(0, 50), amount: cents(i.deposit_amount), description: 'Deposit ' + i.booking_date + ' ' + i.booking_time, quantity: 1 })),
  billing_data: {
    first_name: fw[0],
    last_name: fw.slice(1).join(' '),
    email: 'tg' + chatId + '@example.com',
    phone_number: '+20' + phone.slice(1),
    apartment: 'NA', floor: 'NA', street: 'NA', building: 'NA', city: 'NA', state: 'NA', country: 'EG', postal_code: 'NA'
  },
  special_reference: reference,
  expiration: Number(cfg.link_valid_seconds),
  notification_url: cfg.notification_url,
  redirection_url: cfg.redirection_url,
  extras: { v: 1, kind: kind, chat_id: chatId, customer_name: finalName, customer_phone: phone, amount_egp: amount, items: items, replaces_booking_id: String(inp.replaces_booking_id || '') }
};
const summary = items.map(i => i.service_name + ' ' + i.booking_date + ' ' + i.booking_time + ' (deposit ' + i.deposit_amount + ' EGP)').join(' + ');
return [{ json: { ok: true, reference: reference, amount_egp: amount, summary: summary, chat_id: chatId, hold_expires_ms: holdExpiresMs, holds: holds, paymob_body: body } }];

const cfg = $('Client Config').first().json;
const v = $('Validate & Price').first().json;
const r = $input.first().json;
if (!r || !r.client_secret) {
  return [{ json: { ok: false, error_code: 'PAYMOB_NO_CLIENT_SECRET', message: 'Paymob did not return a checkout session. The booking is NOT made. Offer to retry, reschedule, or contact the clinic.' } }];
}
const url = String(cfg.base_url).replace(/\/$/, '') + '/unifiedcheckout/?publicKey=' + encodeURIComponent(cfg.public_key) + '&clientSecret=' + encodeURIComponent(r.client_secret);
return [{ json: {
  ok: true,
  payment_url: url,
  amount_egp: v.amount_egp,
  reference: v.reference,
  summary: v.summary,
  valid_minutes: Math.round(Number(cfg.link_valid_seconds) / 60),
  instruction: 'Put payment_url on its own line, copy it exactly, and say: Please pay the deposit to secure your slot. The booking is NOT confirmed until the payment succeeds.'
} }];
